    constructor() {
        super({ key: GAME_CONSTANTS.SCENES.BOOT });
    }

    /**
     * 预加载资源
     */
    preload() {
        // 设置加载路径
        this.load.setBaseURL('');

        // 加载加载界面所需的资源
        this.load.setPath('assets/');
    }

    /**
     * 场景创建
     */
    create() {
        console.log('🎮 BootScene: 游戏启动中...');

        // 设置输入系统
        this.setupInput();

        // 设置物理世界边界
        this.setupPhysicsWorld();

        // 跳转到预加载场景
        this.scene.start(GAME_CONSTANTS.SCENES.PRELOAD);
